const item = $input.first();
const body = item.json.body || {};
const binary = item.binary || {};

const errors = [];

const binaryKey = Object.keys(binary)[0];
if (!binaryKey) {
  errors.push('Nenhum arquivo PDF enviado (campo curriculum)');
} else {
  const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  if (!pdfBuffer || pdfBuffer.length < 100) {
    errors.push('Arquivo PDF vazio ou corrompido');
  } else {
    const header = pdfBuffer.slice(0, 5).toString('ascii');
    if (header !== '%PDF-') {
      errors.push('Arquivo nao e um PDF valido (magic bytes invalidos)');
    }
    if (pdfBuffer.length > 10 * 1024 * 1024) {
      errors.push('PDF excede tamanho maximo de 10MB');
    }
  }
}

const jobTitle = body.job_title || '';
if (!jobTitle || jobTitle.trim().length === 0) {
  errors.push('Campo job_title e obrigatorio');
} else if (jobTitle.length > 200) {
  errors.push('job_title excede 200 caracteres');
}

const jobDesc = body.job_description || '';
if (!jobDesc || jobDesc.trim().length === 0) {
  errors.push('Campo job_description e obrigatorio');
} else if (jobDesc.trim().length < 10) {
  errors.push('job_description muito curta (minimo 10 caracteres)');
} else if (jobDesc.length > 50000) {
  errors.push('job_description excede 50000 caracteres');
}

if (errors.length > 0) {
  return [{ json: { _security_failed: true, _stage: 'validacao', error: 'Dados de entrada invalidos', details: errors.map(e => `Campo invalido: ${e}`) } }];
}

return [{ json: { ...body, _binary_key: binaryKey, _security_failed: false } }];

